/**
 * @method
 * @name woofipro#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://orderly.network/docs/build-on-omnichain/restful-api/public/get-system-maintenance-status
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Woofipro) FetchStatusAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Woofipro) fetchStatusBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.V1PublicGetPublicSystemInfo(params))
	PanicOnError(response)
	//
	//     {
	//         "success": true,
	//         "data": {
	//             "status": 0,
	//             "msg": "System is functioning properly."
	//         },
	//         "timestamp": "1709274106602"
	//     }
	//
	var data any = this.SafeDict(response, "data", map[string]any{})
	var status any = this.SafeString(data, "status")
	if IsTrue(IsEqual(status, nil)) {
		status = "error"
	} else if IsTrue(IsEqual(status, "0")) {
		status = "ok"
	} else {
		status = "maintenance"
	}

	ch <- map[string]any{
		"status":  status,
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	}
	return nil
}

