func (this *Woofipro) ParseMarket(market any) any {
	//
	//   {
	//     "symbol": "PERP_BTC_USDC",
	//     "quote_min": 123,
	//     "quote_max": 100000,
	//     "quote_tick": 0.1,
	//     "base_min": 0.00001,
	//     "base_max": 20,
	//     "base_tick": 0.00001,
	//     "min_notional": 1,
	//     "price_range": 0.02,
	//     "price_scope": 0.4,
	//     "std_liquidation_fee": 0.03,
	//     "liquidator_fee": 0.015,
	//     "claim_insurance_fund_discount": 0.0075,
	//     "funding_period": 8,
	//     "cap_funding": 0.000375,
	//     "floor_funding": -0.000375,
	//     "interest_rate": 0.0001,
	//     "created_time": 1684140107326,
	//     "updated_time": 1685345968053,
	//     "base_mmr": 0.05,
	//     "base_imr": 0.1,
	//     "imr_factor": 0.0002512,
	//     "liquidation_tier": "1"
	//   }
	//
	var marketId any = this.SafeString(market, "symbol")
	if IsTrue(IsEqual(marketId, nil)) {
		panic(ExchangeError(Add(this.Id, " parseMarket() missing marketId")))
	}
	var parts []string = Split(marketId, "_")
	var marketType string = "swap"
	var baseId any = this.SafeString(parts, 1)
	var quoteId any = this.SafeString(parts, 2)
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var settleId any = this.SafeString(parts, 2)
	var settle any = this.SafeCurrencyCode(settleId)
	var symbol any = Add(Add(Add(Add(base, "/"), quote), ":"), settle)
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           marketType,
		"spot":           false,
		"margin":         false,
		"swap":           true,
		"future":         false,
		"option":         false,
		"active":         nil,
		"contract":       true,
		"linear":         true,
		"inverse":        false,
		"contractSize":   this.ParseNumber("1"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.SafeNumber(market, "base_tick"),
			"price":  this.SafeNumber(market, "quote_tick"),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.SafeNumber(market, "base_min"),
				"max": this.SafeNumber(market, "base_max"),
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "quote_min"),
				"max": this.SafeNumber(market, "quote_max"),
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "min_notional"),
				"max": nil,
			},
		},
		"created": this.SafeInteger(market, "created_time"),
		"info":    market,
	})
}

